      }
      return new Uint8Array(await response.arrayBuffer());
    })();
    reads.set(url, pending);
  }
  try { return new Uint8Array(await pending); } // No shared mutable bytes/JSON.
  catch (error) {
    if (reads.get(url) === pending) reads.delete(url); // A failed read is retryable.
    throw error;
  }
}

